# V62: font TĨNH (bold / bold-italic) nhúng trực tiếp làm phương án dự phòng.
# Lý do: fontpkg-roboto 3.15 chỉ cung cấp font VARIABLE; ReportLab luôn lấy instance mặc định
# (weight 400) nên mọi chữ đáng lẽ đậm đều bị mất đậm trên Vercel. Bản nhúng dưới đây là font
# tĩnh chuẩn của Roboto nên luôn đậm thật, kể cả khi Vercel không bundle thư mục python/fonts.
_EMBEDDED_BOLD_TTF_B64 = ""

_EMBEDDED_BOLD_ITALIC_TTF_B64 = ""


def _find_font_file(names: Iterable[str]) -> str | None:
    roots = [
        # V62: font tĩnh đi kèm code (python/fonts) — được bundle cùng Python Function.
        Path(__file__).resolve().parent / "fonts",
        Path(os.getenv("REPORTLAB_FONT_DIR", "")) if os.getenv("REPORTLAB_FONT_DIR") else None,
        Path("public/fonts"),
        Path("/usr/share/fonts/truetype/dejavu"),
        Path("/usr/share/fonts/truetype"),
        Path("/usr/share/fonts"),
    ]
    for root in roots:
        if not root or not root.exists():
            continue
        for name in names:
            direct = root / name
            if direct.exists():
                return str(direct)
        try:
            for path in root.rglob("*.ttf"):
                lower = path.name.lower()
                if any(name.lower() == lower for name in names):
                    return str(path)
        except OSError:
            pass
    return None


def _fontpkg_roboto_files() -> tuple[str | None, str | None, str | None, str | None]:
    """Lấy trực tiếp file Roboto từ các package fontpkg trên Vercel.

    `fontpkg.path()` trả về *đường dẫn file font*, không phải thư mục.
    V41.2 đã coi giá trị này là thư mục nên không tìm được .ttf và có thể
    làm Python Function lỗi ngay lúc import trên Vercel.
    """
    try:
        import fontpkg  # type: ignore

        regular = str(fontpkg.path("Roboto"))
        bold = str(fontpkg.path("Roboto", weight=700))
        italic = str(fontpkg.path("Roboto", style="italic"))
        # V60: cần bản bold-italic cho dòng “Ghi chú:” (đậm + nghiêng).
        try:
            bold_italic = str(fontpkg.path("Roboto", weight=700, style="italic"))
        except Exception:
            bold_italic = None
        return regular, bold, italic, bold_italic
    except Exception:
        return None, None, None, None


def _materialize_embedded_font(b64: str, filename: str) -> Any:
    """V62: đưa font nhúng (base64) cho ReportLab đọc.

    Vercel Python Function có thể không bundle file .ttf rời (giống trường hợp logo).
    Ưu tiên ghi ra file tạm; nếu không ghi được thì đưa thẳng BytesIO vì ReportLab
    nhận cả đường dẫn lẫn file object.
    """
    try:
        import tempfile

        target = Path(tempfile.gettempdir()) / filename
        if not target.exists():
            target.write_bytes(base64.b64decode(b64))
        return str(target)
    except Exception:
        try:
            return io.BytesIO(base64.b64decode(b64))
        except Exception:
            return None


def _first_distinct(*candidates: Any, regular: Any = None) -> Any:
    """Chọn nguồn font đầu tiên khác file regular.

    Tránh trường hợp fontpkg-roboto trả về ĐÚNG file regular cho weight=700 → chữ đậm
    lặng lẽ mất đậm.
    """
    for candidate in candidates:
        if not candidate:
            continue
        if (
            isinstance(candidate, str)
            and isinstance(regular, str)
            and os.path.abspath(candidate) == os.path.abspath(regular)
        ):
            continue
        return candidate
    return None


def register_fonts() -> dict[str, str]:
    # V62: ưu tiên font TĨNH (python/fonts → public/fonts → hệ thống), rồi tới bản nhúng base64.
    # Chỉ dùng tới Roboto variable của fontpkg khi không có bản tĩnh nào.
    env_regular = os.getenv("REPORTLAB_FONT_PATH")
    env_bold = os.getenv("REPORTLAB_FONT_BOLD_PATH")
    env_italic = os.getenv("REPORTLAB_FONT_ITALIC_PATH")
    env_bold_italic = os.getenv("REPORTLAB_FONT_BOLDITALIC_PATH")

    fp_regular, fp_bold, fp_italic, fp_bold_italic = _fontpkg_roboto_files()

    regular = (
        env_regular
        or _find_font_file(["Roboto-Regular.ttf"])
        or fp_regular
        or _find_font_file(["DejaVuSans.ttf", "NotoSans-Regular.ttf", "Arial.ttf", "LiberationSans-Regular.ttf"])
    )
    bold = _first_distinct(
        env_bold,
        _find_font_file(["Roboto-Bold.ttf"]),
        _materialize_embedded_font(_EMBEDDED_BOLD_TTF_B64, "gm-roboto-bold.ttf"),
        fp_bold,
        _find_font_file(["DejaVuSans-Bold.ttf", "NotoSans-Bold.ttf", "Arial Bold.ttf", "LiberationSans-Bold.ttf"]),
        regular=regular,
    )
    italic = (
        env_italic
        or _find_font_file(["Roboto-Italic.ttf"])
        or fp_italic
        or _find_font_file(["DejaVuSans-Oblique.ttf", "NotoSans-Italic.ttf", "Arial Italic.ttf", "LiberationSans-Italic.ttf"])
    )
    bold_italic = _first_distinct(
        env_bold_italic,
        _find_font_file(["Roboto-BoldItalic.ttf"]),
        _materialize_embedded_font(_EMBEDDED_BOLD_ITALIC_TTF_B64, "gm-roboto-bolditalic.ttf"),
        fp_bold_italic,
        _find_font_file(["DejaVuSans-BoldOblique.ttf", "NotoSans-BoldItalic.ttf", "Arial Bold Italic.ttf", "LiberationSans-BoldItalic.ttf"]),
        regular=italic or regular,
    )

    if not bold:
        print("[PDF_V2] CẢNH BÁO: không tìm được font đậm (bold) — chữ đậm sẽ hiển thị như chữ thường.", flush=True)

    if regular:
        pdfmetrics.registerFont(TTFont("GM-Regular", regular))
        pdfmetrics.registerFont(TTFont("GM-Bold", bold or regular))
        pdfmetrics.registerFont(TTFont("GM-Italic", italic or regular))
        # V60: không có file bold-italic thì lùi về bold (vẫn đậm) để không lỗi.
        pdfmetrics.registerFont(TTFont("GM-BoldItalic", bold_italic or bold or italic or regular))
        return {
            "regular": "GM-Regular",
            "bold": "GM-Bold",
            "italic": "GM-Italic",
            "bold_italic": "GM-BoldItalic",
        }

    # Không âm thầm dùng Helvetica vì Helvetica không có đủ glyph tiếng Việt.
    raise RuntimeError(
        "Không tìm thấy font Unicode cho PDF V2. Hãy bảo đảm dependency fontpkg-roboto được cài đặt."
    )


FONTS = register_fonts()


def pstyle(name: str, *, size: float = 8, leading: float | None = None, font: str = "regular",
           color: colors.Color = TEXT, align: int = TA_LEFT, **kwargs: Any) -> ParagraphStyle:
    return ParagraphStyle(
        name,
        parent=getSampleStyleSheet()["BodyText"],
        fontName=FONTS[font],
        fontSize=size,
        leading=leading or size * 1.18,
        textColor=color,
        alignment=align,
        spaceBefore=0,
        spaceAfter=0,
        splitLongWords=1,
        **kwargs,
    )


